function cutOffTree(forest) {
  const rows = forest.length;
  const cols = forest[0].length;
  const trees = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (forest[r][c] > 1) {
        trees.push([forest[r][c], r, c]);
      }
    }
  }
  trees.sort((a, b) => a[0] - b[0]);
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const distance = (startRow, startCol, targetRow, targetCol) => {
    if (startRow === targetRow && startCol === targetCol) {
      return 0;
    }
    const seen = Array.from({ length: rows }, () => new Array(cols).fill(false));
    seen[startRow][startCol] = true;
    let queue = [[startRow, startCol]];
    let steps = 0;
    while (queue.length > 0) {
      steps++;
      const next = [];
      for (const [r, c] of queue) {
        for (const [dr, dc] of directions) {
          const nr = r + dr;
          const nc = c + dc;
          if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
          if (seen[nr][nc] || forest[nr][nc] === 0) continue;
          if (nr === targetRow && nc === targetCol) return steps;
          seen[nr][nc] = true;
          next.push([nr, nc]);
        }
      }
      queue = next;
    }
    return -1;
  };
  let total = 0;
  let row = 0;
  let col = 0;
  for (const [, treeRow, treeCol] of trees) {
    const steps = distance(row, col, treeRow, treeCol);
    if (steps === -1) {
      return -1;
    }
    total += steps;
    row = treeRow;
    col = treeCol;
  }
  return total;
}

