function cutOffTree(forest) {
  // All-pairs shortest paths over open cells with Floyd-Warshall, then add up the legs.
  const m = forest.length, n = forest[0].length, cells = m * n, INF = 1e15;
  const dist = Array.from({ length: cells }, (_, a) => Array.from({ length: cells }, (_, b) => (a === b ? 0 : INF)));
  for (let a = 0; a < cells; a++) {
    const r = Math.floor(a / n), c = a % n;
    if (forest[r][c] === 0) continue;
    if (c + 1 < n && forest[r][c + 1] !== 0) dist[a][a + 1] = dist[a + 1][a] = 1;
    if (r + 1 < m && forest[r + 1][c] !== 0) dist[a][a + n] = dist[a + n][a] = 1;
  }
  for (let k = 0; k < cells; k++)
    for (let a = 0; a < cells; a++)
      for (let b = 0; b < cells; b++)
        if (dist[a][k] + dist[k][b] < dist[a][b]) dist[a][b] = dist[a][k] + dist[k][b];
  const order = [];
  forest.forEach((line, r) => line.forEach((h, c) => { if (h > 1) order.push({ h, cell: r * n + c }); }));
  order.sort((x, y) => x.h - y.h);
  let at = 0, sum = 0;
  for (const { cell } of order) {
    if (dist[at][cell] >= INF) return -1;
    sum += dist[at][cell];
    at = cell;
  }
  return sum;
}

