function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(40, 50) : int(1, 5);
  const n = large ? int(40, 50) : int(1, 5);
  const wall = large ? 0.12 + rand() * 0.1 : rand() * 0.4;
  const treeChance = large ? 0.15 + rand() * 0.35 : 0.2 + rand() * 0.5;
  const used = new Set();
  const height = () => {
    for (;;) {
      const h = large ? int(2, 1e9) : int(2, 40);
      if (!used.has(h)) { used.add(h); return h; }
    }
  };
  const forest = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const roll = rand();
    return roll < wall ? 0 : roll < wall + treeChance * (1 - wall) ? height() : 1;
  }));
  if (forest[0][0] === 0) forest[0][0] = 1;
  // Large grids usually clear the trees that cannot be reached, so the answer is a real step count.
  if (large && rand() < 0.75) {
    const seen = Array.from({ length: m }, () => new Array(n).fill(false));
    const stack = [[0, 0]];
    seen[0][0] = true;
    while (stack.length) {
      const [r, c] = stack.pop();
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc] && forest[nr][nc] !== 0) { seen[nr][nc] = true; stack.push([nr, nc]); }
      }
    }
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (!seen[r][c] && forest[r][c] > 1) forest[r][c] = 1;
  }
  if (!forest.some(line => line.some(h => h > 1))) forest[m - 1][n - 1] = height();
  return [forest];
}
